#include <stdio.h>

void printNumbers(int n) {
    for (int i = 1; i <= n; i++) {
        printf("%d\n", i);
    }
}

int main() {
    int n;
    scanf("%d", &n);
    printNumbers(n);
    return 0;
}

#include <stdio.h>

void countdown(int start) {
    while (start >= 1) {
        printf("%d\n", start);
        start--;
    }
    printf("Blast off!\n");
}

int main() {
    int start;
    scanf("%d", &start);
    countdown(start);
    return 0;
}

#include <stdio.h>

int sumNatural(int n) {
    int sum = 0;
    for (int i = 1; i <= n; i++) sum += i;
    return sum;
}

int main() {
    int n;
    scanf("%d", &n);
    int result = sumNatural(n);
    printf("The sum of the first %d natural numbers is: %d\n", n, result);
    return 0;
}

#include <stdio.h>

int factorial(int n) {
    int result = 1;
    for (int i = 2; i <= n; i++) result *= i;
    return result;
}

int main() {
    int num;
    scanf("%d", &num);
    int fact = factorial(num);
    printf("The factorial of %d is: %d\n", num, fact);
    return 0;
}

#include <stdio.h>

void printTable(int num) {
    printf("Multiplication Table for %d:\n", num);
    for (int i = 1; i <= 10; i++) {
        printf("%d x %d = %d\n", num, i, num * i);
    }
}

int main() {
    int num;
    scanf("%d", &num);
    printTable(num);
    return 0;
}

#include <stdio.h>

int reverseDigits(int num) {
    int rev = 0;
    while (num > 0) {
        rev = rev * 10 + num % 10;
        num /= 10;
    }
    return rev;
}

int main() {
    int num;
    scanf("%d", &num);
    printf("Original number: %d\n", num);
    int reversed = reverseDigits(num);
    printf("Reversed number: %d\n", reversed);
    return 0;
}

#include <stdio.h>
#include <math.h>

int isPrime(int num) {
    if (num < 2) return 0;
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

int main() {
    int num;
    scanf("%d", &num);
    if (isPrime(num))
        printf("%d is a Prime Number\n", num);
    else
        printf("%d is Not a Prime Number\n", num);
    return 0;
}

#include <stdio.h>

void printFibonacci(int n) {
    int a = 0, b = 1;
    printf("First %d Fibonacci terms: ", n);
    for (int i = 0; i < n; i++) {
        printf("%d%s", a, (i == n-1) ? "\n" : " ");
        int next = a + b;
        a = b;
        b = next;
    }
}

int main() {
    int n;
    scanf("%d", &n);
    printFibonacci(n);
    return 0;
}

#include <stdio.h>

void loopControl() {
    for (int i = 1; i <= 10; i++) {
        if (i == 3) continue;
        if (i == 7) break;
        printf("%d\n", i);
    }
}

int main() {
    loopControl();
    return 0;
}

#include <stdio.h>

void transactionSimulator(float initial_balance) {
    float balance = initial_balance;
    printf("Current Balance: $%.2f\n", balance);
    while (1) {
        char type;
        float amount;
        if (scanf(" %c", &type) != 1) break;
        if (type == 'Q' || type == 'q') break;
        scanf("%f", &amount);
        if (type == 'D' || type == 'd') {
            balance += amount;
            printf("Deposit $%.2f. New Balance: $%.2f\n", amount, balance);
        } else if (type == 'W' || type == 'w') {
            if (amount > balance)
                printf("Insufficient Funds. Withdrawal of $%.2f failed. Balance remains: $%.2f\n", amount, balance);
            else {
                balance -= amount;
                printf("Withdrawal $%.2f. New Balance: $%.2f\n", amount, balance);
            }
        }
    }
}

int main() {
    float balance;
    scanf("%f", &balance);
    transactionSimulator(balance);
    return 0;
}
